-- TABLE TEAM
CREATE TABLE Player (
    PlayerID INT PRIMARY KEY,
	TeamID INT,
    Name VARCHAR(100),
    Age INT,
    Role VARCHAR(50),
    Nationality VARCHAR(50),
    iscaptain CHAR(1),
    FOREIGN KEY (TeamID) REFERENCES Team(TeamID)
);

