-- 5. Match Schedule
CREATE TABLE MatchSchedule (
    MatchID INT PRIMARY KEY,
    Date DATE,
    StadiumID INT,
    StadiumName VARCHAR(100),
    Team1ID INT,
    Team1Name VARCHAR(100),
    Team2ID INT,
    Team2Name VARCHAR(100),
    Umpire1ID INT, 
    Umpire2ID INT, 
    FOREIGN KEY (StadiumID) REFERENCES Stadium(StadiumID),
    FOREIGN KEY (Team1ID) REFERENCES Team(TeamID),
    FOREIGN KEY (Team2ID) REFERENCES Team(TeamID),
    FOREIGN KEY (Umpire1ID) REFERENCES Umpire(UmpireID), 
    FOREIGN KEY (Umpire2ID) REFERENCES Umpire(UmpireID)  
);

