-- 6. MATCH DETAILS
DROP TABLE IF EXISTS MatchDetails;
CREATE TABLE MatchDetails (
    MatchID INT PRIMARY KEY,
    TossWinnerTeamID INT,
    TossDecision VARCHAR(50),
    WinnerTeamID INT,
    WinMargin VARCHAR(100),
    PlayerOfTheMatchID INT,
    TotalScoreT1 INT,
    TotalScoreT2 INT,
    PlayerOfTheMatchName VARCHAR(100),
    Team1Name VARCHAR(100),
    Team2Name VARCHAR(100),
    TossWinnerTeamName VARCHAR(100),
    WinnerTeamName VARCHAR(100),
    FOREIGN KEY (MatchID) REFERENCES MatchSchedule(MatchID),
    FOREIGN KEY (TossWinnerTeamID) REFERENCES Team(TeamID),
    FOREIGN KEY (WinnerTeamID) REFERENCES Team(TeamID),
    FOREIGN KEY (PlayerOfTheMatchID) REFERENCES Player(PlayerID)
);

