-- 8. Player Match Stats
CREATE TABLE PlayerMatchStats (
    MatchID INT,
    PlayerID INT,
    Runs INT,
    BallsFaced INT,
    Fours INT,
    Sixes INT,
    Wickets INT,
    OversBowled FLOAT,
    Maidens INT,
    Catches INT,
    PRIMARY KEY (MatchID, PlayerID),
    FOREIGN KEY (MatchID) REFERENCES MatchSchedule(MatchID),
    FOREIGN KEY (PlayerID) REFERENCES Player(PlayerID)
);


