-- 11. Rankings 
CREATE TABLE TeamRanking (
    MatchID INT,
    TeamID INT,
    Matches_Played INT,
	matches_won int,
	matches_lost int,
    Points INT,
    PRIMARY KEY (MatchID, TeamID),
    FOREIGN KEY (MatchID) REFERENCES MatchSchedule(MatchID),
    FOREIGN KEY (TeamID) REFERENCES Team(TeamID)
);

