-- QUERIES

-- 1. List all matches played at a stadium with a capacity over 4000
SELECT ms.MatchID, ms.Date, s.Name AS Stadium, s.Capacity
FROM MatchSchedule ms
JOIN Stadium s ON ms.StadiumID = s.StadiumID
WHERE s.Capacity > 4000;

-- 2. Get all matches along with the winning team name and toss decision
SELECT md.MatchID, ms.Date, md.WinnerTeamName, md.TossDecision
FROM MatchDetails md
JOIN MatchSchedule ms ON md.MatchID = ms.MatchID;

-- 3. List all players who were captains in any match
SELECT DISTINCT p.PlayerID, p.Name, t.TeamName
FROM Playing11 pl
JOIN Player p ON pl.PlayerID = p.PlayerID
JOIN Team t ON p.TeamID = t.TeamID
WHERE pl.IsCaptain = 1;

-- 4. Show award winners and the type of award
SELECT a.AwardType, p.Name AS PlayerName, t.TeamName
FROM Award a
JOIN Player p ON a.PlayerID = p.PlayerID
JOIN Team t ON p.TeamID = t.TeamID;

-- 5. List top 10 run-scorers across all matches
SELECT p.Name, SUM(pms.Runs) AS TotalRuns
FROM PlayerMatchStats pms
JOIN Player p ON pms.PlayerID = p.PlayerID
GROUP BY p.Name
ORDER BY TotalRuns DESC
LIMIT 10;

-- 6. List all injured players with injury type and date
SELECT p.Name, i.InjuryType, i.InjuryDate
FROM InjuryReport i
JOIN Player p ON i.PlayerID = p.PlayerID;

-- 7. Count tickets sold by area for each match
SELECT MatchID, AREA, COUNT(*) AS TicketsSold
FROM Ticket
GROUP BY MatchID, AREA;

-- 8. Show rankings after the latest match for each team
SELECT tr.TeamID, t.TeamName, tr.Matches_Played, tr.Points
FROM TeamRanking tr
JOIN Team t ON tr.TeamID = t.TeamID
WHERE (tr.MatchID, tr.TeamID) IN (
    SELECT MAX(MatchID), TeamID
    FROM TeamRanking
    GROUP BY TeamID
);

-- 9. Find players who scored 50+ in a match
SELECT p.Name, pms.MatchID, pms.Runs
FROM PlayerMatchStats pms
JOIN Player p ON pms.PlayerID = p.PlayerID
WHERE pms.Runs >= 50;

-- 10. List all sponsors along with their respective teams
SELECT s.Name AS SponsorName, t.TeamName
FROM Sponsor s
JOIN Team t ON s.TeamID = t.TeamID;

-- 11. Get players who are both captains and have received an award
SELECT DISTINCT p.Name
FROM Player p
JOIN Award a ON p.PlayerID = a.PlayerID
WHERE p.iscaptain = 'Y';

-- 12. Get the total number of matches each team has played
SELECT TeamID, COUNT(DISTINCT MatchID) AS TotalMatches
FROM Playing11
GROUP BY TeamID;

-- 13. List matches where both teams had at least one player with 3+ wickets
SELECT ms.MatchID, ms.Team1Name, ms.Team2Name
FROM MatchSchedule ms
WHERE EXISTS (
    SELECT 1 FROM PlayerMatchStats pms
    JOIN Player p ON p.PlayerID = pms.PlayerID
    WHERE p.TeamID = ms.Team1ID AND pms.MatchID = ms.MatchID AND pms.Wickets >= 3
)
AND EXISTS (
    SELECT 1 FROM PlayerMatchStats pms
    JOIN Player p ON p.PlayerID = pms.PlayerID
    WHERE p.TeamID = ms.Team2ID AND pms.MatchID = ms.MatchID AND pms.Wickets >= 3
);

-- 14. Show average ticket price per match
SELECT MatchID, AVG(Price) AS AvgPrice
FROM Ticket
GROUP BY MatchID;

-- 15. Find stadiums that have hosted more than 5 matches
SELECT s.Name, COUNT(ms.MatchID) AS MatchesHosted
FROM Stadium s
JOIN MatchSchedule ms ON s.StadiumID = ms.StadiumID
GROUP BY s.StadiumID, s.Name
HAVING COUNT(ms.MatchID) > 5;





